import { lazy, Suspense } from "react";

import type { ArticleHeadingsProps } from "./ArticleHeadings";
import type { NeuformCraftEffectProps } from "../neuform-isolated/NeuformCraftEffects";
import type { NeuformIsolatedEffectProps } from "../neuform-isolated/NeuformIsolatedEffects";

export type TextAnimationVariant =
  | "article-headings"
  | "neon-sign"
  | "threeui-intro"
  | "particle-wordmark"
  | "audio-wordmark";

type ArticleHeadingsVariantProps = ArticleHeadingsProps & {
  variant?: "article-headings";
};

type NeonTypographyVariantProps = NeuformCraftEffectProps & {
  variant: "neon-sign";
};

type IsolatedTextVariantProps = NeuformIsolatedEffectProps & {
  variant: "threeui-intro" | "particle-wordmark" | "audio-wordmark";
};

export type TextAnimationCollectionProps =
  | ArticleHeadingsVariantProps
  | NeonTypographyVariantProps
  | IsolatedTextVariantProps;

const ArticleHeadingsVariant = lazy(() =>
  import("./ArticleHeadings").then((module) => ({ default: module.ArticleHeadings })),
);

const NeonTypographyVariant = lazy(() =>
  import("../neuform-isolated/NeuformCraftEffects").then((module) => ({ default: module.NeonTypography })),
);

const ThreeUIIntroVariant = lazy(() =>
  import("../neuform-isolated/NeuformIsolatedEffects").then((module) => ({ default: module.ThreeUIIntro })),
);

const ParticleWordmarkVariant = lazy(() =>
  import("../neuform-isolated/NeuformIsolatedEffects").then((module) => ({ default: module.ParticleWordmark })),
);

const AudioWordmarkVariant = lazy(() =>
  import("../neuform-isolated/NeuformIsolatedEffects").then((module) => ({ default: module.AudioWordmark })),
);

const FALLBACK = <div className="threeui-background" style={{ background: "#090909" }} />;

export function TextAnimationCollection(props: TextAnimationCollectionProps) {
  if (props.variant === "neon-sign") {
    const { variant: _variant, ...variantProps } = props;
    return (
      <Suspense fallback={FALLBACK}>
        <NeonTypographyVariant {...variantProps} />
      </Suspense>
    );
  }

  if (props.variant === "threeui-intro") {
    const { variant: _variant, ...variantProps } = props;
    return (
      <Suspense fallback={FALLBACK}>
        <ThreeUIIntroVariant {...variantProps} />
      </Suspense>
    );
  }

  if (props.variant === "particle-wordmark") {
    const { variant: _variant, ...variantProps } = props;
    return (
      <Suspense fallback={FALLBACK}>
        <ParticleWordmarkVariant {...variantProps} />
      </Suspense>
    );
  }

  if (props.variant === "audio-wordmark") {
    const { variant: _variant, ...variantProps } = props;
    return (
      <Suspense fallback={FALLBACK}>
        <AudioWordmarkVariant {...variantProps} />
      </Suspense>
    );
  }

  const { variant: _variant, ...variantProps } = props;
  return (
    <Suspense fallback={FALLBACK}>
      <ArticleHeadingsVariant {...variantProps} />
    </Suspense>
  );
}

import { useEffect, useRef } from "react";
import { startArticleHeadingDecode } from "./articleHeadingDecode";

export type ArticleHeadingsProps = {
  mode?: "dark" | "light";
  duration?: number;
  stagger?: number;
  scrambleLength?: number;
  preserveChance?: number;
  tailChance?: number;
  className?: string;
};

export const ARTICLE_HEADINGS_DEFAULTS = {
  mode: "dark",
  duration: 560,
  stagger: 140,
  scrambleLength: 10,
  preserveChance: 0.3,
  tailChance: 0.18,
} as const;

export function ArticleHeadings({ mode = ARTICLE_HEADINGS_DEFAULTS.mode, className = "", ...props }: ArticleHeadingsProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const safeMode = mode === "light" ? "light" : "dark";
  const options = { ...ARTICLE_HEADINGS_DEFAULTS, ...props };

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    return startArticleHeadingDecode(root, options);
  }, [options.duration, options.preserveChance, options.scrambleLength, options.stagger, options.tailChance]);

  return (
    <div
      ref={rootRef}
      className={`article-headings-component article-headings-component--${safeMode}${className ? ` ${className}` : ""}`}
      data-mode={safeMode}
    >
      <div className="article-headings-component__header">
        <span>FIELD NOTES</span>
        <span>02 ENTRIES</span>
      </div>
      <article className="article-headings-component__entry">
        <span className="article-headings-component__index">01</span>
        <h2 data-article-heading>Context Is Infrastructure, Not a Prompt</h2>
        <span className="article-headings-component__meta">SYSTEMS NOTE · 8 MIN</span>
      </article>
      <article className="article-headings-component__entry">
        <span className="article-headings-component__index">02</span>
        <h2 data-article-heading>The Last Mile Is Verification</h2>
        <span className="article-headings-component__meta">FIELD GUIDE · 11 MIN</span>
      </article>
    </div>
  );
}

export const ARTICLE_HEADING_DECODE_POOL = "#%&@$/\\<>*+=~ABCDEFGHKMNPRSTUVWXYZ0123456789";

export type ArticleHeadingDecodeOptions = {
  duration: number;
  stagger: number;
  scrambleLength: number;
  preserveChance: number;
  tailChance: number;
};

const clamp = (value: number, min: number, max: number) => Math.max(min, Math.min(max, value));
const easeOut = (value: number) => 1 - Math.pow(1 - value, 2);

export function startArticleHeadingDecode(
  root: HTMLElement,
  options: ArticleHeadingDecodeOptions,
) {
  const frames = new Set<number>();
  const originals = new Map<Text, string>();
  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const decodeElement = (element: HTMLElement, delay: number) => {
    if (reduced) return;

    const nodes: Array<{ node: Text; original: string }> = [];
    const walk = (node: Node) => {
      for (const child of node.childNodes) {
        if (child.nodeType === Node.TEXT_NODE && child.textContent?.trim()) {
          const text = child as Text;
          const original = text.textContent ?? "";
          originals.set(text, original);
          nodes.push({ node: text, original });
        } else if (child.nodeType === Node.ELEMENT_NODE) {
          walk(child);
        }
      }
    };
    walk(element);

    const total = nodes.reduce((sum, node) => sum + node.original.length, 0);
    const start = performance.now() + delay;
    const frame = (now: number) => {
      const progress = clamp((now - start) / Math.max(1, options.duration), 0, 1);
      if (now < start) {
        const id = requestAnimationFrame(frame);
        frames.add(id);
        return;
      }

      let budget = Math.floor(easeOut(progress) * total);
      for (const textNode of nodes) {
        const length = textNode.original.length;
        const revealed = clamp(budget, 0, length);
        budget -= revealed;
        if (revealed >= length) {
          textNode.node.textContent = textNode.original;
          continue;
        }

        let output = textNode.original.slice(0, revealed);
        const scrambleLength = Math.min(length - revealed, Math.round(options.scrambleLength));
        for (let index = 0; index < scrambleLength; index += 1) {
          const original = textNode.original[revealed + index];
          output += original === " " || Math.random() < options.preserveChance
            ? original
            : ARTICLE_HEADING_DECODE_POOL[(Math.random() * ARTICLE_HEADING_DECODE_POOL.length) | 0];
        }
        output += textNode.original
          .slice(revealed + scrambleLength)
          .replace(/\S/g, (character) => Math.random() < options.tailChance
            ? ARTICLE_HEADING_DECODE_POOL[(Math.random() * ARTICLE_HEADING_DECODE_POOL.length) | 0]
            : character);
        textNode.node.textContent = output;
      }

      if (progress < 1) {
        const id = requestAnimationFrame(frame);
        frames.add(id);
      }
    };
    const id = requestAnimationFrame(frame);
    frames.add(id);
  };

  root.querySelectorAll<HTMLElement>("[data-article-heading]").forEach((element, index) => {
    decodeElement(element, index * options.stagger);
  });

  return () => {
    frames.forEach(cancelAnimationFrame);
    originals.forEach((original, node) => {
      node.textContent = original;
    });
  };
}
